1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface ClaimStep {
19	  op: "claim";
20	  policy: number;
21	  incident: { cause: string; damages: Damage[] };
22	}
23	
24	export type Step = QuoteStep | ClaimStep;
25	
26	export interface Scenario {
27	  customer: { yearsWithMHPCO: number };
28	  steps: Step[];
29	}
30	
31	export interface QuoteResult {
32	  premium: number;
33	}
34	
35	export interface ClaimResult {
36	  payout: number;
37	  remainingCap: number;
38	}
39	
40	export interface ScenarioResults {
41	  results: (QuoteResult | ClaimResult)[];
42	}
43	
44	const PROCESSING_FEE = 5;
45	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
46	
47	const BASE_PREMIUMS = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	} as const satisfies Record<string, number>;
55	
56	export type InsurableItemType = keyof typeof BASE_PREMIUMS;
57	
58	const basePremiumForType = (type: string): number =>
59	  BASE_PREMIUMS[type as InsurableItemType];
60	
61	const COMPONENT_BLOCK_SIZE = 3;
62	const COMPONENT_BLOCK_PREMIUM = 60;
63	
64	const countByType = (items: Item[]): Map<string, number> => {
65	  const counts = new Map<string, number>();
66	  for (const item of items) {
67	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
68	  }
69	  return counts;
70	};
71	
72	// A building block of 3 alike components is offered at a special base premium.
73	const basePremiumForGroup = (type: string, count: number): number =>
74	  count === COMPONENT_BLOCK_SIZE
75	    ? COMPONENT_BLOCK_PREMIUM
76	    : count * basePremiumForType(type);
77	
78	const sumBasePremiums = (items: Item[]): number =>
79	  [...countByType(items)].reduce(
80	    (total, [type, count]) => total + basePremiumForGroup(type, count),
81	    0,
82	  );
83	
84	// Premiums are rounded up, in the MHPCO's favour; only the final premium is
85	// rounded, intermediate amounts stay fractional.
86	const roundInMHPCOsFavour = Math.ceil;
87	
88	const quotePremium = (items: Item[]): number => {
89	  const basePremium = sumBasePremiums(items);
90	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
91	  return roundInMHPCOsFavour(
92	    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
93	  );
94	};
95	
96	const runStep = (step: Step): QuoteResult | ClaimResult => {
97	  switch (step.op) {
98	    case "quote":
99	      return { premium: quotePremium(step.items) };
100	    case "claim":
101	      throw new Error("claim steps are not supported yet");
102	  }
103	};
104	
105	export const runScenario = (scenario: Scenario): ScenarioResults => ({
106	  results: scenario.steps.map(runStep),
107	});
